const products = $input.all()
  .map(i => i.json)
  .filter(p => p && p.nombre)
  .slice(0, 100);

const linea = p =>
  `- ${p.nombre} | material: ${p.material ?? '-'} | medidas: ${p.medidas ?? '-'} | precio: ${p.precio ?? '-'} | ${String(p.descripcion ?? '').slice(0, 200)}`;

const catalogo = products.length
  ? products.map(linea).join('\n')
  : 'Catálogo no disponible en este momento. Derivá al equipo de ventas para consultas de products.';

const trigger = $('When chat message received').first().json;

return [{
  json: {
    catalogo,
    chatInput: trigger.chatInput,
    sessionId: trigger.sessionId
  }
}];
